  // to row objects so a single column-derived table renders them.
  const rows: Record<string, unknown>[] = Array.isArray(rawList)
    ? rawList.map((entry) =>
        entry !== null && typeof entry === 'object'
          ? (entry as Record<string, unknown>)
          : { value: entry },
      )
    : [];
